// TH18 v1.00a Stage 4 MainSub03 / Cir02; source st04.ecl.txt:931-945 and 140-215.
// Source t0 = wave start; target phase t0 precedes the first spawn by the 120-frame shell buffer.
const TIME_LIMIT: int = 1520;      // phase timer from phase_begin (120 buffer + 1400 source window)
const SOURCE_LIMIT: int = 1400;    // local estimate: 16-spawn schedule (last 600) + last fire cycle + tail
const OPENING_BUFFER: int = 120;
const TH18_RICE: int = 480;        // copied from engine/touhou-bullets.ecl

// Cir02_at 163-214 EX chain (165-195):
//   type2 ANIM a=1        -> spawn retreat position -= 4*speed (3.0 -> 12px, via sh_dist)
//   2097152 a=20 r=0.01   -> first VELTIME: scalar speed 3.0 -> 0.01 over 20 frames, current angle
//   0x80000000 a=120      -> WAIT 120 (cursor only)
//   2097152 a=120 r=rank  -> second VELTIME: 0.01 -> 2.0/2.5/3.0 over 120 frames
xformdef CIR02_SLOW(target: fx) {
    step_speed(0.01fx, 20);
    wait(20);
    wait(120);
    step_speed(target, 120);
}

// Cir02_at 163-214: et0 type8/color13, etAim mode3 (fixed-direction ring),
// etCount(N,1), etAngle(RANDRAD,0) before every volley, etSpeed(3.0,1.0) with M=1.
// Rank: count/volleys/gap/target = E 10/2/80/2.0, N 20/6/40/2.0,
// H 20/9/30/2.5, LO 20/12/20/3.0. First shot comes after $RAND % 30.
async sub cir02_at(end_frame: int) {
    var rank: int = global(GVAR_RANK);
    var ways: int = 10;
    var volleys: int = 2;
    var gap: int = 80;
    var target: fx = 2fx;
    if rank == 1 { ways = 20; volleys = 6; gap = 40; target = 2fx; }
    else if rank == 2 { ways = 20; volleys = 9; gap = 30; target = 2.5fx; }
    else if rank >= 3 { ways = 20; volleys = 12; gap = 20; target = 3fx; }

    wait(rand(30));                       // wait($RAND % 30) at 166
    sh_reset(0);                          // etNew(0) at 167
    sh_sprite(0, TH18_RICE, 13);          // etSprite(0,8,13)
    sh_ring(0, 1);                        // etAim(0,3): fixed-direction whole ring
    sh_aim(0, 0);
    sh_count(0, ways, 1);                 // etCount(0,N,1)
    sh_speed(0, 3fx, 0fx);                // etSpeed(0,3.0,1.0), M=1 -> first value only
    sh_dist(0, -12fx);                    // ANIM a=1: position -= 4*velocity
    sh_xform(0, CIR02_SLOW(target));      // EX 184-195
    for k in 0..volleys {
        if $frame >= end_frame { return; }
        sh_angle(0, rand(65536) as angle, 0deg); // etAngle(0,RANDRAD,0) at 199
        sh_fire(0);
        wait(gap);                        // rank wait at 201-209
    }
}

// Cir02 140-161: hurtbox 28 / hitbox 16, spawn at (0,-32) relative to the parent,
// ABS velocity 1.0 at 90deg ramping to 0.5 over 80 frames (mode0 linear),
// REL ellipse theta0=%F0, omega=1deg, r=144, d=0, beta=ABS_ANGLE=90deg, scale=0.
// With s=0 the REL contribution is (144*cos(theta), 0) about the captured center.
async sub cir02_main(end_frame: int, phase0: angle) {
    set_invuln(65535);
    set_hurtbox(14fx);                    // source setHurtbox(28,28)
    set_hitbox(8fx);                      // source setHitbox(16,16)
    var theta: angle = phase0;
    var py: fx = -32fx;                   // ABS layer y; REL ellipse only offsets x
    move_to(0, 144fx * cos(theta), py, EASE_LINEAR); // ellipse setter applies immediately
    var age: int = 0;
    loop {
        if $frame >= end_frame { return; }
        age = age + 1;
        var sp: fx = 0.5fx;
        if age <= 80 { sp = 1fx - 0.5fx * (age as fx) / 80fx; } // moveVelTime 80 mode0
        py = py + sp;
        theta = theta + 1deg;             // 0.017453292 rad/frame
        move_to(0, 144fx * cos(theta), py, EASE_LINEAR);
        if age == 80 { spawn cir02_at(end_frame); } // wait(80) then async at (153-154)
        wait(1);
    }
}

// MainSub03 931-945: 16 planned creations at local 0..600 every 40 frames.
// %F0 = RANDRAD (validRad normalizes) is snapshotted into each child at creation.
async sub wave_pattern() {
    wait(OPENING_BUFFER);
    var start: int = $frame;
    var end: int = start + SOURCE_LIMIT;
    for i in 0..16 {
        var phase: angle = rand(65536) as angle;
        _ = spawn_enemy(144fx * cos(phase), -32fx, 1200, 0, 0, 0,
                        cir02_main(end, phase));
        wait(40);
    }
}

// Control enemy shell at (0,0): no body collision, invulnerable phase owner.
async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
